insert into gate_questions (year, question_number, original_label, set_label, subject, type, question_text, options, correct_answer, explanation, marks) values (2000, 2, '2.19', null, 'Graph Search', 'MCQ', 'Let be an undirected graph. Consider a depth-ﬁrst traversal of , and let be the resulting depth-ﬁrst search tree. Let be a vertex in and let be the ﬁrst new (unvisited) vertex visited after visiting in the traversal. Which of the following statement is always true?', '{"A": "must be an edge in , and is a descendant of in", "B": "must be an edge in , and is a descendant of in", "C": "If is not an edge in then is a leaf in", "D": "If is not an edge in then and must have the same parent in"}'::jsonb, '["C"]'::jsonb, null, 1) on conflict (year, subject, original_label, set_label) do update set question_number = excluded.question_number, type = excluded.type, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer, marks = excluded.marks;
