insert into gate_questions (year, question_number, original_label, set_label, subject, type, question_text, options, correct_answer, explanation, marks) values (2021, 41, '41', 'Set 1', 'Tree', 'MCQ', 'An in a connected graph is a vertex such that removing the vertex and its incident edges disconnects the graph into two or more connected components. Let be a tree obtained by doing in a connected undirected graph . Which of the following options is/are correct?', '{"A": "Root of can never be an articulation point in .", "B": "Root of is an articulation point in if and only if it has or more children.", "C": "A leaf of can be an articulation point in .", "D": "If is an articulation point in such that is an ancestor of in and is a descendent of in , then all paths from to in must pass through ."}'::jsonb, '["B"]'::jsonb, null, 2) on conflict (year, subject, original_label, set_label) do update set question_number = excluded.question_number, type = excluded.type, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer, marks = excluded.marks;
insert into gate_questions (year, question_number, original_label, set_label, subject, type, question_text, options, correct_answer, explanation, marks) values (2024, 23, '23', 'Set 2', 'Output', 'MSQ', '​​​ Consider the following function definition. int fX ( char * a ) { char * b = a ; while (* b ) b ++; return b - a ; } Which of the following statements is/are TRUE?', '{"A": "The function call fX(\"abcd\") will always return a value", "B": "Assuming a character array c is declared as char c[]= \"abcd\" in main () , the function call fX(c) will always return a value", "C": "The code of the function will not compile", "D": "Assuming a character pointer c is declared as char *c=\"abcd\" in main (), the function call fX(c) will always return a value"}'::jsonb, '["A", "B", "D"]'::jsonb, null, 1) on conflict (year, subject, original_label, set_label) do update set question_number = excluded.question_number, type = excluded.type, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer, marks = excluded.marks;
