insert into gate_questions (year, question_number, original_label, set_label, subject, type, question_text, options, correct_answer, explanation, marks) values (2001, 2, '2.18', null, 'Pointers', 'MCQ', 'Consider the following three C functions: int * g ( void ) { int x = 10 ; return (& x ); } int * g ( void ) { int * px ; * px = 10 ; return px ; } int * g ( void ) { int * px ; px = ( int *) malloc ( sizeof ( int )); * px = 10 ; return px ; }', '{"A": "Only", "B": "Only and", "C": "Only and", "D": "and"}'::jsonb, '["C"]'::jsonb, null, 1) on conflict (year, subject, original_label, set_label) do update set question_number = excluded.question_number, type = excluded.type, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer, marks = excluded.marks;
insert into gate_questions (year, question_number, original_label, set_label, subject, type, question_text, options, correct_answer, explanation, marks) values (2005, 1, '1, ISRO2017-55', null, 'Pointers', 'MCQ', 'What does the following C-statement declare? int (*f) (int * );', '{"A": "A function that takes an integer pointer as argument and returns an integer", "B": "A function that takes an integer as argument and returns an integer pointer", "C": "A pointer to a function that takes an integer pointer as argument and returns an integer", "D": null}'::jsonb, '["C"]'::jsonb, null, 1) on conflict (year, subject, original_label, set_label) do update set question_number = excluded.question_number, type = excluded.type, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer, marks = excluded.marks;
