insert into gate_questions (year, question_number, original_label, set_label, subject, type, question_text, options, correct_answer, explanation, marks) values (1992, 5, '5-a', null, 'Average Memory Access Time', 'NAT', 'The access times of the main memory and the Cache memory, in a computer system, are n sec and nsec, respectively. It is estimated that of the main memory request are for read the rest for write. The hit ratio for the read access only is and a write-through policy (where both main and cache memories are updated simultaneously) is used. Determine the average time of the main memory (in ns).', null::jsonb, '{"value": 180}'::jsonb, null, 1) on conflict (year, subject, original_label, set_label) do update set question_number = excluded.question_number, type = excluded.type, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer, marks = excluded.marks;
insert into gate_questions (year, question_number, original_label, set_label, subject, type, question_text, options, correct_answer, explanation, marks) values (2025, 43, '43', 'Set 1', 'Average Memory Access Time', 'NAT', 'A computer has a memory hierarchy consisting of two-level cache and and a main memory. If the processor needs to access data from memory, it ﬁrst looks into cache. If the data is not found in cache, it goes to cache. If it fails to get the data from cache, it goes to main memory, where the data is deﬁnitely available. Hit rates and access times of various memory units are shown in the ﬁgure. The average memory access time in nanoseconds is ________. (rounded off to two decimal places)', null::jsonb, '{"min": 11.83, "max": 11.87}'::jsonb, null, 2) on conflict (year, subject, original_label, set_label) do update set question_number = excluded.question_number, type = excluded.type, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer, marks = excluded.marks;
insert into gate_questions (year, question_number, original_label, set_label, subject, type, question_text, options, correct_answer, explanation, marks) values (2025, 45, '45', 'Set 2', 'Average Memory Access Time', 'NAT', 'Given a computing system with two levels of cache (L1 and L2) and a main memory. The ﬁrst level (L1) cache access time is nanosecond (ns) and the "hit rate" for L1 cache is while the processor is accessing the data from L1 cache. Whereas, for the second level (L2) cache, the "hit rate" is and the "miss penalty" for transferring data from L2 cache to L1 cache is ns . The "miss penalty" for the data to be transferred from main memory to L2 cache is ns . Then the average memory access time in this system in nanoseconds is __________ . (rounded oﬀ to one decimal place)', null::jsonb, '{"min": 4.0, "max": 4.0}'::jsonb, null, 2) on conflict (year, subject, original_label, set_label) do update set question_number = excluded.question_number, type = excluded.type, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer, marks = excluded.marks;
insert into gate_questions (year, question_number, original_label, set_label, subject, type, question_text, options, correct_answer, explanation, marks) values (2026, 43, '43', 'Set 2', 'Bit Vector', 'NAT', 'To keep track of free blocks in a ﬁle system, one of the two approaches is generally used - using bitmaps (bit vectors) or using linked lists. Consider that the linked list approach is used to keep track of free blocks in a ﬁle system. Assume that the disk size is GB , block size is KB , and block numbers used are -bit long. A single pointer of size bytes is used in each block of the list to point to the next block of the list. The number of blocks required to hold the free disk block numbers is . (answer in integer) Note: and', null::jsonb, '{"value": 16417}'::jsonb, null, 2) on conflict (year, subject, original_label, set_label) do update set question_number = excluded.question_number, type = excluded.type, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer, marks = excluded.marks;
insert into gate_questions (year, question_number, original_label, set_label, subject, type, question_text, options, correct_answer, explanation, marks) values (1990, 7, '7a', null, 'Cache Memory', 'NAT', 'A block-set associative cache memory consists of blocks divided into four block sets. The main memory consists of blocks and each block contains eight bit words. 1 . How many bits are required for addressing the main memory? 2 . How many bits are needed to represent the TAG, SET and WORD fields?', null::jsonb, '{"value": 22}'::jsonb, null, 1) on conflict (year, subject, original_label, set_label) do update set question_number = excluded.question_number, type = excluded.type, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer, marks = excluded.marks;
