insert into gate_questions (year, question_number, original_label, set_label, subject, type, question_text, options, correct_answer, explanation, marks) values (2014, 44, '44', 'Set 1', 'Cache Memory', 'MCQ', 'An access sequence of cache block addresses is of length and contains n unique block addresses. The number of unique block addresses between two consecutive accesses to the same block address is bounded above by . What is the miss ratio if the access sequence is passed through a cache of associativity exercising least-recently-used replacement policy?', '{"A": "Width of tag comparator", "B": "Width of set index decoder", "C": "Width of way selection multiplexer", "D": "Width of processor to main memory data bus"}'::jsonb, '["A"]'::jsonb, null, 1) on conflict (year, subject, original_label, set_label) do update set question_number = excluded.question_number, type = excluded.type, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer, marks = excluded.marks;
insert into gate_questions (year, question_number, original_label, set_label, subject, type, question_text, options, correct_answer, explanation, marks) values (2014, 43, '43', 'Set 2', 'Cache Memory', 'MCQ', 'In designing a computer''s cache system, the cache block (or cache line) size is an important parameter. Which one of the following statements is correct in this context?', '{"A": "A smaller block size implies better spatial locality", "B": "A smaller block size implies a smaller cache tag and hence lower cache tag overhead", "C": "A smaller block size implies a larger cache tag and hence lower cache hit time", "D": "A smaller block size incurs a lower cache miss penalty"}'::jsonb, '["D"]'::jsonb, null, 1) on conflict (year, subject, original_label, set_label) do update set question_number = excluded.question_number, type = excluded.type, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer, marks = excluded.marks;
