insert into gate_questions (year, question_number, original_label, set_label, subject, type, question_text, options, correct_answer, explanation, marks) values (2014, 44, '44', 'Set 3', 'Cache Memory', 'NAT', 'The memory access time is nanosecond for a read operation with a hit in cache, nanoseconds for a read operation with a miss in cache, nanoseconds for a write operation with a hit in cache and nanoseconds for a write operation with a miss in cache. Execution of a sequence of instructions involves instruction fetch operations, memory operand read operations and memory operand write operations. The cache hit-ratio is . The average memory access time (in nanoseconds) in executing the sequence of instructions is ______.', null::jsonb, '{"value": 1.68}'::jsonb, null, 1) on conflict (year, subject, original_label, set_label) do update set question_number = excluded.question_number, type = excluded.type, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer, marks = excluded.marks;
