insert into gate_questions (year, question_number, original_label, set_label, subject, type, question_text, options, correct_answer, explanation, marks) values (2019, 45, '45', null, 'Cache Memory', 'NAT', 'A certain processor deploys a single-level cache. The cache block size is words and the word size is bytes. The memory system uses a -MHz clock. To service a cache miss, the memory controller ﬁrst takes cycle to accept the starting address of the block, it then takes cycles to fetch all the eight words of the block, and ﬁnally transmits the words of the requested block at the rate of word per cycle. The maximum bandwidth for the memory system when the program running on the processor issues a series of read operations is ______ bytes/sec.', null::jsonb, '{"value": 160}'::jsonb, null, 2) on conflict (year, subject, original_label, set_label) do update set question_number = excluded.question_number, type = excluded.type, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer, marks = excluded.marks;
insert into gate_questions (year, question_number, original_label, set_label, subject, type, question_text, options, correct_answer, explanation, marks) values (2020, 30, '30', null, 'Cache Memory', 'MCQ', 'A computer system with a word length of bits has a MB byte- addressable main memory and a KB, -way set associative cache memory with a block size of bytes. Consider the following four physical addresses represented in hexadecimal notation. , , , Which one of the following is TRUE?', '{"A": "and are mapped to different cache sets.", "B": "and are mapped to the same cache set.", "C": "and are mapped to the same cache set.", "D": "and are mapped to the same cache set."}'::jsonb, '["B"]'::jsonb, null, 2) on conflict (year, subject, original_label, set_label) do update set question_number = excluded.question_number, type = excluded.type, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer, marks = excluded.marks;
