insert into gate_questions (year, question_number, original_label, set_label, subject, type, question_text, options, correct_answer, explanation, marks) values (2016, 10, '10', 'Set 2', 'Machine Instruction', 'NAT', 'A processor has distinct instruction and general purpose registers. A -bit instruction word has an opcode, two registers operands and an immediate operand. The number of bits available for the immediate operand field is_______.', null::jsonb, '{"value": 16}'::jsonb, null, 1) on conflict (year, subject, original_label, set_label) do update set question_number = excluded.question_number, type = excluded.type, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer, marks = excluded.marks;
insert into gate_questions (year, question_number, original_label, set_label, subject, type, question_text, options, correct_answer, explanation, marks) values (2021, 55, '55', 'Set 1', 'Machine Instruction', 'NAT', 'Consider the following instruction sequence where registers and are general purpose and denotes the content at the memory location Assume that the content of the memory location is , and the content of the register is . The content of each of the memory locations from to is . The instruction sequence starts from the memory location . All the numbers are in decimal format. Assume that the memory is byte addressable. After the execution of the program, the content of memory location is ____________', null::jsonb, '{"min": 50.0, "max": 50.0}'::jsonb, null, 2) on conflict (year, subject, original_label, set_label) do update set question_number = excluded.question_number, type = excluded.type, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer, marks = excluded.marks;
insert into gate_questions (year, question_number, original_label, set_label, subject, type, question_text, options, correct_answer, explanation, marks) values (2016, 9, '09', 'Set 1', 'Memory Interfacing', 'NAT', 'A processor can support a maximum memory of , where the memory is word-addressable (a word consists of two bytes). The size of address bus of the processor is at least _________bits.', null::jsonb, '{"value": 31}'::jsonb, null, 1) on conflict (year, subject, original_label, set_label) do update set question_number = excluded.question_number, type = excluded.type, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer, marks = excluded.marks;
insert into gate_questions (year, question_number, original_label, set_label, subject, type, question_text, options, correct_answer, explanation, marks) values (2018, 23, '23', null, 'Memory Interfacing', 'NAT', 'A wide main memory unit with a capacity of is built using DRAM chips. The number of rows of memory cells in the DRAM chip is . The time taken to perform one refresh operation is . The refresh period is The percentage (rounded to the closest integer) of the time available for performing the memory read/write operations in the main memory unit is _________.', null::jsonb, '{"min": 59.0, "max": 60.0}'::jsonb, null, 1) on conflict (year, subject, original_label, set_label) do update set question_number = excluded.question_number, type = excluded.type, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer, marks = excluded.marks;
insert into gate_questions (year, question_number, original_label, set_label, subject, type, question_text, options, correct_answer, explanation, marks) values (1999, 2, '2.19', null, 'Microprogramming', 'MCQ', 'Arrange the following configuration for CPU in decreasing order of operating speeds: Hard wired control, Vertical microprogramming, Horizontal microprogramming.', '{"A": "Hard wired control, Vertical microprogramming, Horizontal microprogramming.", "B": "Hard wired control, Horizontal microprogramming, Vertical microprogramming.", "C": "Horizontal microprogramming, Vertical microprogramming, Hard wired control.", "D": "Vertical microprogramming, Horizontal microprogramming, Hard wired control."}'::jsonb, '["B"]'::jsonb, null, 1) on conflict (year, subject, original_label, set_label) do update set question_number = excluded.question_number, type = excluded.type, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer, marks = excluded.marks;
insert into gate_questions (year, question_number, original_label, set_label, subject, type, question_text, options, correct_answer, explanation, marks) values (2002, 2, '2.7', null, 'Microprogramming', 'MCQ', 'Horizontal microprogramming:', '{"A": "does not require use of signal decoders", "B": "results in larger sized microinstructions than vertical  microprogramming", "C": "uses one bit for each control signal", "D": "all of the above"}'::jsonb, '["D"]'::jsonb, null, 1) on conflict (year, subject, original_label, set_label) do update set question_number = excluded.question_number, type = excluded.type, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer, marks = excluded.marks;
insert into gate_questions (year, question_number, original_label, set_label, subject, type, question_text, options, correct_answer, explanation, marks) values (2005, 45, '45', null, 'Microprogramming', 'MCQ', 'A hardwired CPU uses control signals to , in various time steps to , to implement instructions to as shown below: Which of the following pairs of expressions represent the circuit for generating control signals and respectively? indicates that the control signal should be generated in time step if the instruction being executed is or', '{"A": "and", "B": "and", "C": "and", "D": "and"}'::jsonb, '["D"]'::jsonb, null, 1) on conflict (year, subject, original_label, set_label) do update set question_number = excluded.question_number, type = excluded.type, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer, marks = excluded.marks;
insert into gate_questions (year, question_number, original_label, set_label, subject, type, question_text, options, correct_answer, explanation, marks) values (1999, 13, '13', null, 'Pipelining', 'NAT', 'An instruction pipeline consists of stages – Fetch , Decode ﬁeld , Execute and Result Write . The instructions in a certain instruction sequence need these stages for the diﬀerent number of clock cycles as shown by the table below 1.24.2', null::jsonb, '{"value": 15}'::jsonb, null, 1) on conflict (year, subject, original_label, set_label) do update set question_number = excluded.question_number, type = excluded.type, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer, marks = excluded.marks;
insert into gate_questions (year, question_number, original_label, set_label, subject, type, question_text, options, correct_answer, explanation, marks) values (2002, 2, '2.6, ISRO2008-19', null, 'Pipelining', 'MCQ', 'The performance of a pipelined processor suffers if:', '{"A": "the pipeline stages have different delays", "B": "consecutive instructions are dependent on each other", "C": "the pipeline stages share hardware resources", "D": "All of the above"}'::jsonb, '["D"]'::jsonb, null, 1) on conflict (year, subject, original_label, set_label) do update set question_number = excluded.question_number, type = excluded.type, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer, marks = excluded.marks;
insert into gate_questions (year, question_number, original_label, set_label, subject, type, question_text, options, correct_answer, explanation, marks) values (2007, 37, '37, ISRO2009-37', null, 'Pipelining', 'MCQ', 'Consider a pipelined processor with the following four stages: IF: Instruction Fetch ID: Instruction Decode and Operand Fetch EX: Execute WB: Write Back The IF, ID and WB stages take one clock cycle each to complete the operation. The number of clock cycles for the EX stage depends on the instruction. The ADD and SUB instructions need clock cycle and the MUL instruction needs clock cycles in the EX stage. Operand forwarding is used in the pipelined processor. What is the number of clock cycles taken to complete the following sequence of instructions? 1.24.10 1.24.11', '{"A": "I1", "B": "I2", "C": "I3", "D": "I4"}'::jsonb, '["B"]'::jsonb, null, 1) on conflict (year, subject, original_label, set_label) do update set question_number = excluded.question_number, type = excluded.type, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer, marks = excluded.marks;
insert into gate_questions (year, question_number, original_label, set_label, subject, type, question_text, options, correct_answer, explanation, marks) values (2008, 76, '76', null, 'Pipelining', 'MCQ', 'Delayed branching can help in the handling of control hazards For all delayed conditional branch instructions, irrespective of whether the condition evaluates to true or false,', '{"A": "The instruction following the conditional branch instruction in memory is executed", "B": "The first instruction in the fall through path is executed", "C": "The first instruction in the taken path is executed", "D": "The branch takes longer to execute than any other instruction"}'::jsonb, '["A"]'::jsonb, null, 1) on conflict (year, subject, original_label, set_label) do update set question_number = excluded.question_number, type = excluded.type, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer, marks = excluded.marks;
insert into gate_questions (year, question_number, original_label, set_label, subject, type, question_text, options, correct_answer, explanation, marks) values (2012, 20, '20,', null, 'Pipelining', 'MCQ', 'ISRO2016-23 Register renaming is done in pipelined processors:', '{"A": "as an alternative to register allocation at compile time", "B": "for efficient access to function parameters and local variables", "C": "to handle certain kinds of hazards", "D": "as part of address translation"}'::jsonb, '["C"]'::jsonb, null, 1) on conflict (year, subject, original_label, set_label) do update set question_number = excluded.question_number, type = excluded.type, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer, marks = excluded.marks;
insert into gate_questions (year, question_number, original_label, set_label, subject, type, question_text, options, correct_answer, explanation, marks) values (2015, 38, '38', 'Set 1', 'Pipelining', 'NAT', 'Consider a non-pipelined processor with a clock rate of gigahertz and average cycles per instruction of four. The same processor is upgraded to a pipelined processor with ﬁve stages; but due to the internal pipeline delay, the clock speed is reduced to gigahertz. Assume that there are no stalls in the pipeline. The speedup achieved in this pipelined processor is_______________.', null::jsonb, '{"value": 3.2}'::jsonb, null, 1) on conflict (year, subject, original_label, set_label) do update set question_number = excluded.question_number, type = excluded.type, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer, marks = excluded.marks;
insert into gate_questions (year, question_number, original_label, set_label, subject, type, question_text, options, correct_answer, explanation, marks) values (2015, 44, '44', 'Set 2', 'Pipelining', 'NAT', 'Consider the sequence of machine instruction given below: In the above sequence, to are general purpose registers. In the instructions shown, the ﬁrst register shows the result of the operation performed on the second and the third registers. This sequence of instructions is to be executed in a pipelined instruction processor with the following stages: Instruction Fetch and Decode , Operand Fetch , Perform Operation and Write back the result . The , and stages take clock cycle each for any instruction. The stage takes clock cycle for ADD and SUB instruction, clock cycles for MUL instruction and clock cycles for DIV instruction. The pipelined processor uses 1.24.21 1.24.22 1.24.23 1.24.24 operand forwarding from the PO stage to the OF stage. The number of clock cycles taken for the execution of the above sequence of instruction is _________.', null::jsonb, '{"value": 13}'::jsonb, null, 1) on conflict (year, subject, original_label, set_label) do update set question_number = excluded.question_number, type = excluded.type, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer, marks = excluded.marks;
insert into gate_questions (year, question_number, original_label, set_label, subject, type, question_text, options, correct_answer, explanation, marks) values (2015, 51, '51', 'Set 3', 'Pipelining', 'NAT', 'Consider the following reservation table for a pipeline having three stages . The minimum average latency (MAL) is ______', null::jsonb, '{"value": 3}'::jsonb, null, 1) on conflict (year, subject, original_label, set_label) do update set question_number = excluded.question_number, type = excluded.type, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer, marks = excluded.marks;
insert into gate_questions (year, question_number, original_label, set_label, subject, type, question_text, options, correct_answer, explanation, marks) values (2016, 33, '33', 'Set 2', 'Pipelining', 'NAT', 'Consider a (gigahertz) processor with a three stage pipeline and stage latencies and such that . If the longest pipeline stage is split into two pipeline stages of equal latency , the new frequency is __________ , ignoring delays in the pipeline registers.', null::jsonb, '{"value": 4}'::jsonb, null, 1) on conflict (year, subject, original_label, set_label) do update set question_number = excluded.question_number, type = excluded.type, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer, marks = excluded.marks;
insert into gate_questions (year, question_number, original_label, set_label, subject, type, question_text, options, correct_answer, explanation, marks) values (2018, 50, '50', null, 'Pipelining', 'NAT', 'The instruction pipeline of a RISC processor has the following stages: Instruction Fetch , Instruction Decode , Operand Fetch , Perform Operation and Writeback , The , , and stages take clock cycle each for every instruction. Consider a sequence of instructions. In the stage, instructions take clock cycles each, instructions take clock cycles each, and the remaining instructions take clock cycle each. Assume that there are no data hazards and no control hazards. The number of clock cycles required for completion of execution of the sequence of instruction is _____.', null::jsonb, '{"value": 219}'::jsonb, null, 2) on conflict (year, subject, original_label, set_label) do update set question_number = excluded.question_number, type = excluded.type, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer, marks = excluded.marks;
insert into gate_questions (year, question_number, original_label, set_label, subject, type, question_text, options, correct_answer, explanation, marks) values (2020, 43, '43', null, 'Pipelining', 'NAT', 'Consider a non-pipelined processor operating at GHz. It takes clock cycles to complete an instruction. You are going to make a - stage pipeline out of this processor. Overheads associated with pipelining force you to operate the pipelined processor at GHz. In a given program, assume that are memory instructions, are ALU instructions and the rest are branch instructions. of the memory instructions cause stalls of clock cycles each due to cache misses and of the branch instructions cause stalls of cycles each. Assume that there are no stalls associated with the execution of ALU instructions. For this program, the speedup achieved by the pipelined processor over the non-pipelined processor (round off to decimal places) is_____________.', null::jsonb, '{"min": 2.15, "max": 2.18}'::jsonb, null, 2) on conflict (year, subject, original_label, set_label) do update set question_number = excluded.question_number, type = excluded.type, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer, marks = excluded.marks;
insert into gate_questions (year, question_number, original_label, set_label, subject, type, question_text, options, correct_answer, explanation, marks) values (2021, 53, '53', 'Set 2', 'Pipelining', 'NAT', 'Consider a pipelined processor with stages, , , , , and . Each stage of the pipeline, except the stage, takes one cycle. Assume that the stage merely decodes the instruction and the register read is performed in the stage. The stage takes one cycle for instruction and two cycles for instruction. Ignore pipeline register latencies. Consider the following sequence of instructions: Assume that every instruction is data-dependent on the instruction just before it and every instruction (except the ﬁrst ) is data-dependent on the instruction just before it. The deﬁned as follows. The achieved in executing the given instruction sequence on the pipelined processor (rounded to decimal places) is _____________', null::jsonb, '{"min": 1.87, "max": 1.88}'::jsonb, null, 2) on conflict (year, subject, original_label, set_label) do update set question_number = excluded.question_number, type = excluded.type, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer, marks = excluded.marks;
insert into gate_questions (year, question_number, original_label, set_label, subject, type, question_text, options, correct_answer, explanation, marks) values (2023, 23, '23', null, 'Pipelining', 'NAT', 'Consider a -stage pipelined processor having a delay of (nanoseconds), , and for the ﬁrst, second, and the third stages, respectively. Assume that there is no other delay and the processor does not suffer from any pipeline hazards. Also assume that one instruction is fetched every cycle. The total execution time for executing instructions on this processor is _____________', null::jsonb, '{"value": 2040}'::jsonb, null, 1) on conflict (year, subject, original_label, set_label) do update set question_number = excluded.question_number, type = excluded.type, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer, marks = excluded.marks;
insert into gate_questions (year, question_number, original_label, set_label, subject, type, question_text, options, correct_answer, explanation, marks) values (2024, 20, '20', 'Set 1', 'Pipelining', 'MSQ', 'Consider a -stage pipelined processor with Instruction Fetch (IF), Instruction Decode (ID), Execute (EX), Memory Access (MEM), and Register Writeback (WB) stages. Which of the following statements about forwarding is/are CORRECT?', '{"A": "In a pipelined execution, forwarding means the result from a source stage of an earlier instruction is passed on to the destination stage of a later instruction", "B": "In forwarding, data from the output of the MEM stage can be passed on to the input of the EX stage of the next instruction", "C": "Forwarding cannot prevent all pipeline stalls", "D": "Forwarding does not require any extra hardware to retrieve the data from the pipeline stages"}'::jsonb, '["A", "B", "C"]'::jsonb, null, 1) on conflict (year, subject, original_label, set_label) do update set question_number = excluded.question_number, type = excluded.type, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer, marks = excluded.marks;
insert into gate_questions (year, question_number, original_label, set_label, subject, type, question_text, options, correct_answer, explanation, marks) values (2024, 21, '21', 'Set 2', 'Pipelining', 'MCQ', '​​​​​ An instruction format has the following structure: Instruction Number: Opcode destination reg, source reg- , source reg- Consider the following sequence of instructions to be executed in a pipelined processor: Which of the following statements is/are TRUE?', '{"A": "There is a RAW dependency on between and", "B": "There is a WAR dependency on between and", "C": "There is a RAW dependency on between and", "D": "There is a WAW dependency on between and"}'::jsonb, '["A"]'::jsonb, null, 1) on conflict (year, subject, original_label, set_label) do update set question_number = excluded.question_number, type = excluded.type, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer, marks = excluded.marks;
insert into gate_questions (year, question_number, original_label, set_label, subject, type, question_text, options, correct_answer, explanation, marks) values (2024, 48, '48', 'Set 2', 'Pipelining', 'NAT', 'A non-pipelined instruction execution unit operating at takes an average of cycles to execute an instruction of a program . The unit is then redesigned to operate on a -stage pipeline at . Assume that the ideal throughput of the pipelined unit is instruction per cycle. In the execution of program , instructions incur an average of cycles stall due to data hazards and instructions incur an average of cycles stall due to control hazards. The speedup (rounded oﬀ to one decimal place) obtained by the pipelined design over the non-pipelined design is ____________.', null::jsonb, '{"value": 3}'::jsonb, null, 2) on conflict (year, subject, original_label, set_label) do update set question_number = excluded.question_number, type = excluded.type, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer, marks = excluded.marks;
insert into gate_questions (year, question_number, original_label, set_label, subject, type, question_text, options, correct_answer, explanation, marks) values (2025, 46, '46', 'Set 2', 'Pipelining', 'NAT', 'A -stage instruction pipeline has stage delays of , and , respectively, in nanoseconds. The delay of an inter-stage latch is nanoseconds. Assume that there are no pipeline stalls due to branches and other hazards. The time taken to process instructions in microseconds is __________. (rounded off to two decimal places)', null::jsonb, '{"min": 260.2, "max": 261.2}'::jsonb, null, 2) on conflict (year, subject, original_label, set_label) do update set question_number = excluded.question_number, type = excluded.type, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer, marks = excluded.marks;
insert into gate_questions (year, question_number, original_label, set_label, subject, type, question_text, options, correct_answer, explanation, marks) values (2014, 43, '43', 'Set 1', 'Speedup', 'NAT', 'Consider a -stage instruction pipeline, where all stages are perfectly balanced. Assume that there is no cycle-time overhead of pipelining. When an application is executing on this -stage pipeline, the speedup achieved with respect to non-pipelined execution if % of the instructions incur pipeline stall cycles is ____________', null::jsonb, '{"value": 4}'::jsonb, null, 1) on conflict (year, subject, original_label, set_label) do update set question_number = excluded.question_number, type = excluded.type, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer, marks = excluded.marks;
insert into gate_questions (year, question_number, original_label, set_label, subject, type, question_text, options, correct_answer, explanation, marks) values (2014, 55, '55', 'Set 1', 'Speedup', 'NAT', 'Consider two processors and executing the same instruction set. Assume that under identical conditions, for the same input, a program running on takes less time but incurs more CPI (clock cycles per instruction) as compared to the program running on . If the clock frequency of is , then the clock frequency of (in GHz) is ______.', null::jsonb, '{"value": 1.6}'::jsonb, null, 1) on conflict (year, subject, original_label, set_label) do update set question_number = excluded.question_number, type = excluded.type, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer, marks = excluded.marks;
insert into gate_questions (year, question_number, original_label, set_label, subject, type, question_text, options, correct_answer, explanation, marks) values (2024, 45, '45', 'Set 1', 'Speedup', 'NAT', 'The baseline execution time of a program on a single core machine is nanoseconds ( . The code corresponding to of the execution time can be fully parallelized. The overhead for using an additional core is when running on a multicore system. Assume that all cores in the multicore system run their share of the parallelized code for an equal amount of time. The number of cores that minimize the execution time of the program is __________.', null::jsonb, '{"value": 3}'::jsonb, null, 2) on conflict (year, subject, original_label, set_label) do update set question_number = excluded.question_number, type = excluded.type, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer, marks = excluded.marks;
insert into gate_questions (year, question_number, original_label, set_label, subject, type, question_text, options, correct_answer, explanation, marks) values (2026, 47, '47', 'Set 2', 'Speedup', 'NAT', 'A non-pipelined instruction execution unit that operates at GHz clock takes an average of clock cycles to complete the execution of an instruction. To improve the performance, the system was pipelined with a goal of achieving an average throughput of one instruction per clock cycle. However, it could operate only at GHz due to pipeline overheads. While executing a program in the pipelined design, of instructions encountered a stall of cycles due to pipeline hazards. The speed-up obtained by the pipelined design over the non-pipelined one for this program is (rounded off to two decimal places) Note:', null::jsonb, '{"min": 2.3, "max": 2.4}'::jsonb, null, 2) on conflict (year, subject, original_label, set_label) do update set question_number = excluded.question_number, type = excluded.type, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer, marks = excluded.marks;
insert into gate_questions (year, question_number, original_label, set_label, subject, type, question_text, options, correct_answer, explanation, marks) values (2022, 51, '51', null, 'Stall', 'NAT', 'A processor operating at has a standard stage instruction pipeline having a base of one without any pipeline hazards. For a given program that has branch instructions, control hazards incur cycles stall for every branch. A new version of the processor operating at same clock frequency has an additional branch predictor unit that completely eliminates stalls for correctly predicted branches. There is neither any savings nor any additional stalls for wrong predictions. There are no structural hazards and data hazards for and If the has a prediction accuracy of the speed up obtained by over in executing is _______________.', null::jsonb, '{"min": 1.42, "max": 1.45}'::jsonb, null, 2) on conflict (year, subject, original_label, set_label) do update set question_number = excluded.question_number, type = excluded.type, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer, marks = excluded.marks;
insert into gate_questions (year, question_number, original_label, set_label, subject, type, question_text, options, correct_answer, explanation, marks) values (2008, 38, '38', null, 'Virtual Memory', 'MCQ', 'In an instruction execution pipeline, the earliest that the data TLB (Translation Lookaside Buﬀer) can be accessed is:', '{"A": "before effective address calculation has started", "B": "during effective address calculation", "C": "after effective address calculation has completed", "D": "after data cache lookup has completed"}'::jsonb, '["C"]'::jsonb, null, 1) on conflict (year, subject, original_label, set_label) do update set question_number = excluded.question_number, type = excluded.type, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer, marks = excluded.marks;
insert into gate_questions (year, question_number, original_label, set_label, subject, type, question_text, options, correct_answer, explanation, marks) values (2016, 25, '25', 'Set 1', 'Application Layer Protocols', 'MCQ', 'Which of the following is/are example(s) of stateful application layer protocol?', '{"A": "and only", "B": "and only", "C": "and only", "D": "only"}'::jsonb, '["C"]'::jsonb, null, 1) on conflict (year, subject, original_label, set_label) do update set question_number = excluded.question_number, type = excluded.type, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer, marks = excluded.marks;
insert into gate_questions (year, question_number, original_label, set_label, subject, type, question_text, options, correct_answer, explanation, marks) values (2020, 25, '25', null, 'Application Layer Protocols', 'NAT', 'Assume that you have made a request for a web page through your web browser to a web server. Initially the browser cache is empty. Further, the browser is conﬁgured to send requests in non-persistent mode. The web page contains text and ﬁve very small images.The minimum number of connections required to display the web page completely in your browser is__________.', null::jsonb, '{"value": 6}'::jsonb, null, 1) on conflict (year, subject, original_label, set_label) do update set question_number = excluded.question_number, type = excluded.type, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer, marks = excluded.marks;
insert into gate_questions (year, question_number, original_label, set_label, subject, type, question_text, options, correct_answer, explanation, marks) values (2022, 25, '25', null, 'Application Layer Protocols', 'NAT', 'Consider the resolution of the domain name by a resolver. Assume that no resource records are cached anywhere across the servers and that iterative query mechanism is used in the resolution. The number of query-response pairs involved in completely resolving the domain name is ________________.', null::jsonb, '{"value": 4}'::jsonb, null, 1) on conflict (year, subject, original_label, set_label) do update set question_number = excluded.question_number, type = excluded.type, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer, marks = excluded.marks;
insert into gate_questions (year, question_number, original_label, set_label, subject, type, question_text, options, correct_answer, explanation, marks) values (2026, 9, '9', 'Set 1', 'Application Layer Protocols', 'MSQ', 'Which of the following statements is/are true with respect to the interaction of a web browser with a web server using HTTP ?', '{"A": "HTTP facilitates downloading multiple objects of the same webpage over the same TCP connection, if the objects are stored in the same server", "B": "HTTP facilitates downloading multiple objects of the same webpage over the same TCP connection, even if they are stored in different servers", "C": "HTTP facilitates sending a request for downloading one object without waiting for a previously requested object to be downloaded completely", "D": "HTTP facilitates downloading multiple webpages on the same server to be downloaded over a single TCP connection"}'::jsonb, '["A", "C", "D"]'::jsonb, null, 1) on conflict (year, subject, original_label, set_label) do update set question_number = excluded.question_number, type = excluded.type, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer, marks = excluded.marks;
insert into gate_questions (year, question_number, original_label, set_label, subject, type, question_text, options, correct_answer, explanation, marks) values (2026, 12, '12', 'Set 2', 'Application Layer Protocols', 'MCQ', 'Which one of the following protocols may need to broadcast some of its messages?', '{"A": "HTTP, SMTP, FTP", "B": "FTP, HTTP, SMTP", "C": "HTTP, FTP, SMTP", "D": "SMTP, HTTP, FTP"}'::jsonb, '["C"]'::jsonb, null, 1) on conflict (year, subject, original_label, set_label) do update set question_number = excluded.question_number, type = excluded.type, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer, marks = excluded.marks;
insert into gate_questions (year, question_number, original_label, set_label, subject, type, question_text, options, correct_answer, explanation, marks) values (2005, 77, '77', null, 'Application Layer Protocols', 'MCQ', 'Assume that "host1.mydomain.dom" has an IP address of . Which of the following options would be most appropriate as a subsequence of steps in performing the reverse lookup of ? In the following options "NS" is an abbreviation of "nameserver".', '{"A": "Query a NS for the root domain and then NS for the \"dom\" domains", "B": "Directly query a NS for \"dom\" and then a NS for \"mydomain.dom\" domains", "C": "Query a NS for in-addr.arpa and then a NS for in-addr.arpa domains", "D": "Directly query a NS for in-addr.arpa and then a NS for in-addr.arpa domains"}'::jsonb, '["C"]'::jsonb, null, 1) on conflict (year, subject, original_label, set_label) do update set question_number = excluded.question_number, type = excluded.type, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer, marks = excluded.marks;
insert into gate_questions (year, question_number, original_label, set_label, subject, type, question_text, options, correct_answer, explanation, marks) values (2025, 6, '6', 'Set 2', 'Arp', 'MCQ', '​​​​​ Consider the following statements: i . Address Resolution Protocol (ARP) provides a mapping from an IP address to the corresponding hardware (link-layer) address. ii . A single TCP segment from a sender to a receiver cannot carry both data from to and acknowledgement for a segment from to Which one of the following is CORRECT?', '{"A": "Both and are TRUE", "B": "is TRUE and is FALSE", "C": "is FALSE and is TRUE", "D": "Both and are FALSE"}'::jsonb, '["B"]'::jsonb, null, 1) on conflict (year, subject, original_label, set_label) do update set question_number = excluded.question_number, type = excluded.type, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer, marks = excluded.marks;
insert into gate_questions (year, question_number, original_label, set_label, subject, type, question_text, options, correct_answer, explanation, marks) values (2004, 16, '16', null, 'Bridges', 'MCQ', 'Which of the following is NOT true with respect to a transparent bridge and a router?', '{"A": "Both bridge and router selectively forward data packets", "B": "A bridge uses IP addresses while a router uses MAC addresses", "C": "A bridge builds up its routing table by inspecting incoming packets", "D": "A router can connect between a LAN and a WAN"}'::jsonb, '["B"]'::jsonb, null, 1) on conflict (year, subject, original_label, set_label) do update set question_number = excluded.question_number, type = excluded.type, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer, marks = excluded.marks;
insert into gate_questions (year, question_number, original_label, set_label, subject, type, question_text, options, correct_answer, explanation, marks) values (2016, 53, '53', 'Set 2', 'CSMA CD', 'NAT', 'A network has a data transmission bandwidth of bits per second. It uses CSMA/CD in the MAC layer. The maximum signal propagation time from one node to another node is microseconds. The minimum size of a frame in the network is __________ bytes.', null::jsonb, '{"value": 200}'::jsonb, null, 1) on conflict (year, subject, original_label, set_label) do update set question_number = excluded.question_number, type = excluded.type, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer, marks = excluded.marks;
insert into gate_questions (year, question_number, original_label, set_label, subject, type, question_text, options, correct_answer, explanation, marks) values (2018, 55, '55', null, 'CSMA CD', 'NAT', 'Consider a simple communication system where multiple nodes are connected by a shared broadcast medium (like Ethernet or wireless). The nodes in the system use the following carrier-sense based medium access protocol. A node that receives a packet to transmit will carrier-sense the medium for units of time. If the node does not detect any other transmission, it starts transmitting its packet in the next time unit. If the node detects another transmission, it waits until this other transmission ﬁnishes, and then begins to carrier-sense for time units again. Once they start to transmit, nodes do not perform any collision detection and continue transmission even if a collision occurs. All transmissions last for units of time. Assume that the transmission signal travels at the speed of meters per unit time in the medium. Assume that the system has two nodes and , located at a distance meters from each other. start transmitting a packet at time after successfully completing its carrier-sense phase. Node has a packet to 2.6.4 2.6.5', null::jsonb, '{"value": 50}'::jsonb, null, 2) on conflict (year, subject, original_label, set_label) do update set question_number = excluded.question_number, type = excluded.type, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer, marks = excluded.marks;
insert into gate_questions (year, question_number, original_label, set_label, subject, type, question_text, options, correct_answer, explanation, marks) values (2005, 27, '27', null, 'CSMA CD', 'MCQ', 'Which of the following statements is TRUE about CSMA/CD:', '{"A": "IEEE wireless LAN runs CSMA/CD protocol", "B": "Ethernet is not based on CSMA/CD protocol", "C": "CSMA/CD is not suitable for a high propagation delay network like satellite network", "D": "There is no contention in a CSMA/CD network"}'::jsonb, '["C"]'::jsonb, null, 1) on conflict (year, subject, original_label, set_label) do update set question_number = excluded.question_number, type = excluded.type, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer, marks = excluded.marks;
insert into gate_questions (year, question_number, original_label, set_label, subject, type, question_text, options, correct_answer, explanation, marks) values (2022, 49, '49', null, 'Communication', 'NAT', 'Consider a link between an earth station (sender) and a satellite (receiver) at an altitude of The signal propagates at a speed of The time taken for the receiver to completely receive a packet of transmitted by the sender is _______________.', null::jsonb, '{"min": 7.07, "max": 7.09}'::jsonb, null, 2) on conflict (year, subject, original_label, set_label) do update set question_number = excluded.question_number, type = excluded.type, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer, marks = excluded.marks;
insert into gate_questions (year, question_number, original_label, set_label, subject, type, question_text, options, correct_answer, explanation, marks) values (2012, 45, '45', null, 'Congestion Control', 'MCQ', 'Consider an instance of TCP’s Additive Increase Multiplicative Decrease (AIMD) algorithm where the window size at the start of the slow start phase is MSS and the threshold at the start of the ﬁrst transmission is MSS. Assume that a timeout occurs during the fifth transmission. Find the congestion window size at the end of the tenth transmission.', '{"A": "MSS", "B": "MSS", "C": "MSS", "D": "MSS"}'::jsonb, '["C"]'::jsonb, null, 1) on conflict (year, subject, original_label, set_label) do update set question_number = excluded.question_number, type = excluded.type, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer, marks = excluded.marks;
insert into gate_questions (year, question_number, original_label, set_label, subject, type, question_text, options, correct_answer, explanation, marks) values (2014, 27, '27', 'Set 1', 'Congestion Control', 'NAT', 'Let the size of congestion window of a TCP connection be KB when a timeout occurs. The round trip time of the connection is msec and the maximum segment size used is KB. The time taken (in msec) by the TCP connection to get back to KB congestion window is _________.', null::jsonb, '{"value": 1100}'::jsonb, null, 1) on conflict (year, subject, original_label, set_label) do update set question_number = excluded.question_number, type = excluded.type, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer, marks = excluded.marks;
insert into gate_questions (year, question_number, original_label, set_label, subject, type, question_text, options, correct_answer, explanation, marks) values (2020, 55, '55', null, 'Congestion Control', 'NAT', 'Consider a connection between a client and a server with the following speciﬁcations; the round trip time is ms, the size of the receiver advertised window is KB, slow-start threshold at the client is KB, and the maximum segment size is KB. The connection is established at time . Assume that there are no timeouts and errors during transmission. Then the size of the congestion window (in ) at time ms after all acknowledgements are processed is _______', null::jsonb, '{"value": 44}'::jsonb, null, 2) on conflict (year, subject, original_label, set_label) do update set question_number = excluded.question_number, type = excluded.type, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer, marks = excluded.marks;
insert into gate_questions (year, question_number, original_label, set_label, subject, type, question_text, options, correct_answer, explanation, marks) values (2024, 44, '44', 'Set 2', 'Congestion Control', 'NAT', 'Consider a connection operating at a point of time with the congestion window of size (Maximum Segment Size), when a timeout occurs due to packet loss. Assuming that all the segments transmitted in the next two (Round Trip Time) are acknowledged correctly, the congestion window size ( in ) during the third will be __________.', null::jsonb, '{"value": 4}'::jsonb, null, 2) on conflict (year, subject, original_label, set_label) do update set question_number = excluded.question_number, type = excluded.type, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer, marks = excluded.marks;
insert into gate_questions (year, question_number, original_label, set_label, subject, type, question_text, options, correct_answer, explanation, marks) values (2026, 48, '48', 'Set 2', 'Congestion Control', 'NAT', 'Consider a new TCP connection between a sender and a receiver. The receiver advertised window is constant at KB, the maximum segment size (MSS) is KB, and the slow start threshold for TCP congestion control is KB. Assume that there are no timeouts or duplicate acknowledgements. The number of rounds of transmission required for the congestion control algorithm of the TCP connection to reach the congestion avoidance phase is . (answer in integer) Note:', null::jsonb, '{"min": 4.0, "max": 4.0}'::jsonb, null, 2) on conflict (year, subject, original_label, set_label) do update set question_number = excluded.question_number, type = excluded.type, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer, marks = excluded.marks;
insert into gate_questions (year, question_number, original_label, set_label, subject, type, question_text, options, correct_answer, explanation, marks) values (2026, 55, '55', 'Set 2', 'Data Communication', 'NAT', 'It is necessary to design a link-layer protocol between two hosts that are directly connected over a lossless link of length kilometers. Assume that the link bandwidth is bits per second and that the propagation delay in the link is nanoseconds per meter. Every transmitted data byte is assigned a unique sequence number. Let be the minimum number of bits needed for the sequence number field in the protocol header such that i . the sequence numbers do not wrap around before seconds, and ii . the maximum utilization of the link is achieved. The value of is . (answer in integer)', null::jsonb, '{"min": 30.0, "max": 30.0}'::jsonb, null, 2) on conflict (year, subject, original_label, set_label) do update set question_number = excluded.question_number, type = excluded.type, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer, marks = excluded.marks;
insert into gate_questions (year, question_number, original_label, set_label, subject, type, question_text, options, correct_answer, explanation, marks) values (2011, 53, '53', null, 'Distance Vector Routing', 'MCQ', 'Consider a network with five nodes, to , as shown as below. The network uses a Distance Vector Routing protocol. Once the routes have been stabilized, the distance vectors at different nodes are as follows. N1 : N2 : N3 : N4 : N5 : Each distance vector is the distance of the best known path at that instance to nodes, to , where the distance to itself is . Also, all links are symmetric and the cost is identical in both directions. In each round, all nodes exchange their distance vectors with their respective neighbors. Then all nodes update their distance vectors. In between two rounds, any change in cost of a link will cause the two incident nodes to change only that entry in their distance vectors. The cost of link reduces to (in both directions). After the next round of updates, the link goes down. will reﬂect this change immediately in its distance vector as cost, . After the NEXT ROUND of update, what will be the cost to in the distance vector of ?', '{"A": "link state routing protocol.", "B": "distance vector routing protocol", "C": "DNS while resolving host name", "D": "TCP for congestion control"}'::jsonb, '["C"]'::jsonb, null, 1) on conflict (year, subject, original_label, set_label) do update set question_number = excluded.question_number, type = excluded.type, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer, marks = excluded.marks;
insert into gate_questions (year, question_number, original_label, set_label, subject, type, question_text, options, correct_answer, explanation, marks) values (2021, 45, '45', 'Set 2', 'Distance Vector Routing', 'MSQ', 'Consider a computer network using the distance vector routing algorithm in its network layer. The partial topology of the network is shown below. The objective is to ﬁnd the shortest-cost path from the router to routers and . Assume that does not initially know the shortest routes to and . Assume that has three neighbouring routers denoted as , and . During one iteration, measures its distance to its neighbours , , and as , and , respectively. Router gets routing vectors from its neighbours that indicate that the distance to router from routers , and are , and , respectively. The routing vector also indicates that the distance to router from routers , and are , and respectively. Which of the following statement(s) is/are correct with respect to the new routing table o , after updation during this iteration?', '{"A": "The distance from to will be stored as", "B": "The distance from to will be stored as", "C": "The next hop router for a packet from to is", "D": "The next hop router for a packet from to is"}'::jsonb, '["B", "C"]'::jsonb, null, 2) on conflict (year, subject, original_label, set_label) do update set question_number = excluded.question_number, type = excluded.type, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer, marks = excluded.marks;
insert into gate_questions (year, question_number, original_label, set_label, subject, type, question_text, options, correct_answer, explanation, marks) values (2022, 47, '47', null, 'Distance Vector Routing', 'NAT', 'Consider a network with three routers shown in the figure below. All the links have cost of unity. The routers exchange distance vector routing information and have converged on the routing tables, after which the link fails. Assume that and send out routing updates at random times, each at the same average rate. The probability of a routing loop formation (rounded oﬀ to one decimal place) between and leading to count- to-infinity problem, is _______________.', null::jsonb, '{"value": 0.5}'::jsonb, null, 2) on conflict (year, subject, original_label, set_label) do update set question_number = excluded.question_number, type = excluded.type, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer, marks = excluded.marks;
insert into gate_questions (year, question_number, original_label, set_label, subject, type, question_text, options, correct_answer, explanation, marks) values (1992, 1, '01,ii', null, 'Error Detection', 'NAT', 'Consider a -bit error detection and -bit error correction hamming code for -bit data. The extra parity bits required would be _____ and the -bit error detection is possible because the code has a minimum distance of _______.', null::jsonb, '{"min": 3.0, "max": 4.0}'::jsonb, null, 1) on conflict (year, subject, original_label, set_label) do update set question_number = excluded.question_number, type = excluded.type, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer, marks = excluded.marks;
insert into gate_questions (year, question_number, original_label, set_label, subject, type, question_text, options, correct_answer, explanation, marks) values (2009, 48, '48', null, 'Error Detection', 'MCQ', 'Let be the generator polynomial used for CRC checking. What is the condition that should be satisﬁed by to detect odd number of bits in error?', '{"A": "contains more than two terms", "B": "does not divide , for any not exceeding the frame length", "C": "is a factor of", "D": "has an odd number of terms."}'::jsonb, '["C"]'::jsonb, null, 1) on conflict (year, subject, original_label, set_label) do update set question_number = excluded.question_number, type = excluded.type, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer, marks = excluded.marks;
insert into gate_questions (year, question_number, original_label, set_label, subject, type, question_text, options, correct_answer, explanation, marks) values (2016, 24, '24', 'Set 2', 'Ethernet', 'MCQ', 'In an Ethernet local area network, which one of the following statements is TRUE ?', '{"A": "A station stops to sense the channel once it starts transmitting a frame.", "B": "The purpose of the jamming signal is to pad the frames that are smaller than the minimum frame size.", "C": "A station continues to transmit the packet even after the collision is detected.", "D": "The exponential back off mechanism reduces the probability of collision on retransmissions."}'::jsonb, '["D"]'::jsonb, null, 1) on conflict (year, subject, original_label, set_label) do update set question_number = excluded.question_number, type = excluded.type, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer, marks = excluded.marks;
