insert into gate_questions (year, question_number, original_label, set_label, subject, type, question_text, options, correct_answer, explanation, marks) values (2024, 45, '45', 'Set 2', 'Ethernet', 'NAT', 'Consider an Ethernet segment with a transmission speed of and a maximum segment length of meters. If the speed of propagation of the signal in the medium is , then the minimum frame size ( in bits ) required for collision detection is ___________.', null::jsonb, '{"value": 500}'::jsonb, null, 2) on conflict (year, subject, original_label, set_label) do update set question_number = excluded.question_number, type = excluded.type, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer, marks = excluded.marks;
