insert into gate_questions (year, question_number, original_label, set_label, subject, type, question_text, options, correct_answer, explanation, marks) values (2025, 47, '47', 'Set 1', 'Fragmentation', 'NAT', 'Suppose a message of size bytes is transmitted from a source to a destination using IPv4 protocol via two routers as shown in the ﬁgure. Each router has a deﬁned maximum transmission unit (MTU) as shown in the ﬁgure, including IP header. The number of fragments that will be delivered to the destination is _________. (Answer in integer)', null::jsonb, '{"min": 7.0, "max": 7.0}'::jsonb, null, 2) on conflict (year, subject, original_label, set_label) do update set question_number = excluded.question_number, type = excluded.type, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer, marks = excluded.marks;
