insert into gate_questions (year, question_number, original_label, set_label, subject, type, question_text, options, correct_answer, explanation, marks) values (2003, 27, '27', null, 'IP Addressing', 'MCQ', 'Which of the following assertions is FALSE about the Internet Protocol (IP)?', '{"A": "It is possible for a computer to have multiple IP addresses", "B": "IP packets from the same source to the same destination can take different routes in the network", "C": "IP ensures that a packet is discarded if it is unable to reach its destination within a given number of hops", "D": "The packet source cannot set the route of an outgoing packets; the route is determined only by the routing tables in the routers on the way"}'::jsonb, '["D"]'::jsonb, null, 1) on conflict (year, subject, original_label, set_label) do update set question_number = excluded.question_number, type = excluded.type, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer, marks = excluded.marks;
