insert into gate_questions (year, question_number, original_label, set_label, subject, type, question_text, options, correct_answer, explanation, marks) values (2006, 5, '5', null, 'IP Packet', 'MCQ', 'For which one of the following reasons does internet protocol(IP) use the time-to-live(TTL) ﬁeld in IP datagram header?', '{"A": "Ensure packets reach destination within that time", "B": "Discard packets that reach later than that time", "C": "Prevent packets from looping indefinitely", "D": "Limit the time for which a packet gets queued in intermediate routers"}'::jsonb, '["C"]'::jsonb, null, 1) on conflict (year, subject, original_label, set_label) do update set question_number = excluded.question_number, type = excluded.type, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer, marks = excluded.marks;
