insert into gate_questions (year, question_number, original_label, set_label, subject, type, question_text, options, correct_answer, explanation, marks) values (2024, 55, '55', 'Set 1', 'IP Packet', 'NAT', 'Consider sending an datagram of size bytes (including bytes of header) from a sender to a receiver over a path of two links with a router between them. The ﬁrst link (sender to router) has an (Maximum Transmission Unit) size of bytes, while the second link (router to receiver) has an size of bytes. The number of fragments that would be delivered at the receiver is ____________.', null::jsonb, '{"value": 6}'::jsonb, null, 2) on conflict (year, subject, original_label, set_label) do update set question_number = excluded.question_number, type = excluded.type, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer, marks = excluded.marks;
insert into gate_questions (year, question_number, original_label, set_label, subject, type, question_text, options, correct_answer, explanation, marks) values (2024, 18, '18', 'Set 2', 'IP Packet', 'MSQ', '​​​​​ Which of the following statements about fragmentation is/are TRUE?', '{"A": "The fragmentation of an datagram is performed only at the source of the datagram", "B": "The fragmentation of an datagram is performed at any router which ﬁnds that the size of the datagram to be transmitted exceeds the", "C": "The reassembly of fragments is performed only at the destination of the datagram", "D": "The reassembly of fragments is performed at all intermediate routers along the path from the source to the destination"}'::jsonb, '["B", "C"]'::jsonb, null, 1) on conflict (year, subject, original_label, set_label) do update set question_number = excluded.question_number, type = excluded.type, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer, marks = excluded.marks;
