insert into gate_questions (year, question_number, original_label, set_label, subject, type, question_text, options, correct_answer, explanation, marks) values (2005, 26, '26', null, 'Icmp', 'MCQ', 'Traceroute reports a possible route that is taken by packets moving from some host to some other host . Which of the following options represents the technique used by traceroute to identify these hosts:', '{"A": "By progressively querying routers about the next router on the path to using packets, starting with the first router", "B": "By requiring each router to append the address to the packet as it is forwarded to . The list of all routers en-route to is returned by in an reply packet", "C": "By ensuring that an reply packet is returned to by each router en-route to in the ascending order of their hop distance from", "D": "By locally computing the shortest path from to"}'::jsonb, '["A"]'::jsonb, null, 1) on conflict (year, subject, original_label, set_label) do update set question_number = excluded.question_number, type = excluded.type, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer, marks = excluded.marks;
