insert into gate_questions (year, question_number, original_label, set_label, subject, type, question_text, options, correct_answer, explanation, marks) values (2015, 8, '8', 'Set 2', 'MAC Protocol', 'NAT', 'A link has transmission speed of bits/sec. It uses data packets of size each. Assume that the acknowledgment has negligible transmission delay and that its propagation delay is the same as the data propagation delay. Also, assume that the processing delays at nodes are negligible. The eﬃciency of the stop- and-wait protocol in this setup is exactly . The value of the one way propagation delay (in milliseconds) is_____.', null::jsonb, '{"value": 12}'::jsonb, null, 1) on conflict (year, subject, original_label, set_label) do update set question_number = excluded.question_number, type = excluded.type, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer, marks = excluded.marks;
insert into gate_questions (year, question_number, original_label, set_label, subject, type, question_text, options, correct_answer, explanation, marks) values (2013, 14, '14', null, 'Network Layer', 'MCQ', 'Assume that source S and destination D are connected through two intermediate routers labeled R. Determine how many times each packet has to visit the network layer and the data link layer during a transmission from S to D.', '{"A": "Network layer – times and Data link layer – times", "B": "Network layer – times and Data link layer – times", "C": "Network layer – times and Data link layer – times", "D": "Network layer – times and Data link layer – times"}'::jsonb, '["C"]'::jsonb, null, 1) on conflict (year, subject, original_label, set_label) do update set question_number = excluded.question_number, type = excluded.type, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer, marks = excluded.marks;
insert into gate_questions (year, question_number, original_label, set_label, subject, type, question_text, options, correct_answer, explanation, marks) values (2005, 24, '24', null, 'Network Protocols', 'MCQ', 'The address resolution protocol (ARP) is used for:', '{"A": "Finding the IP address from the DNS", "B": "Finding the IP address of the default gateway", "C": "Finding the IP address that corresponds to a MAC address", "D": "Finding the MAC address that corresponds to an IP address"}'::jsonb, '["D"]'::jsonb, null, 1) on conflict (year, subject, original_label, set_label) do update set question_number = excluded.question_number, type = excluded.type, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer, marks = excluded.marks;
insert into gate_questions (year, question_number, original_label, set_label, subject, type, question_text, options, correct_answer, explanation, marks) values (2019, 29, '29', null, 'Network Protocols', 'MCQ', 'Suppose that in an IP-over-Ethernet network, a machine X wishes to ﬁnd the MAC address of another machine Y in its subnet. Which one of the following techniques can be used for this?', '{"A": "X sends an ARP request packet to the local gateway’s IP address which then ﬁnds the MAC address of Y and sends to X", "B": "X sends an ARP request packet to the local gateway’s MAC address which then ﬁnds the MAC address of Y and sends to X", "C": "X sends an ARP request packet with broadcast MAC address in its local subnet", "D": "X sends an ARP request packet with broadcast IP address in its local subnet"}'::jsonb, '["C"]'::jsonb, null, 2) on conflict (year, subject, original_label, set_label) do update set question_number = excluded.question_number, type = excluded.type, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer, marks = excluded.marks;
insert into gate_questions (year, question_number, original_label, set_label, subject, type, question_text, options, correct_answer, explanation, marks) values (2021, 49, '49', 'Set 1', 'Network Protocols', 'NAT', 'Consider the sliding window ﬂow-control protocol operating between a sender and a receiver over a full- duplex error-free link. Assume the following: The time taken for processing the data frame by the receiver is negligible. The time taken for processing the acknowledgement frame by the sender is negligible. The sender has infinite number of frames available for transmission. The size of the data frame is bits and the size of the acknowledgement frame is bits. The link data rate in each direction is Mbps ( bits per second). One way propagation delay of the link is milliseconds. 2.23.8', null::jsonb, '{"min": 50.0, "max": 52.0}'::jsonb, null, 2) on conflict (year, subject, original_label, set_label) do update set question_number = excluded.question_number, type = excluded.type, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer, marks = excluded.marks;
insert into gate_questions (year, question_number, original_label, set_label, subject, type, question_text, options, correct_answer, explanation, marks) values (2007, 69, '69', null, 'Network Protocols', 'MCQ', 'Consider the following clauses: i . Not inherently suitable for client authentication. ii . Not a state sensitive protocol. iii . Must be operated with more than one server. iv . Suitable for structured message organization. v . May need two ports on the serve side for proper operation. The option that has the maximum number of correct matches is', '{"A": "IMAP-i;  FTP-ii;  HTTP-iii;  DNS-iv;  POP3-v", "B": "FTP-i;  POP3-ii;  SMTP-iii;  HTTP-iv;  IMAP-v", "C": "POP3-i;  SMTP-ii;  DNS-iii;  IMAP-iv;  HTTP-v", "D": "SMTP-i;  HTTP-ii;  IMAP-iii;  DNS-iv;  FTP-v"}'::jsonb, '["D"]'::jsonb, null, 1) on conflict (year, subject, original_label, set_label) do update set question_number = excluded.question_number, type = excluded.type, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer, marks = excluded.marks;
