insert into gate_questions (year, question_number, original_label, set_label, subject, type, question_text, options, correct_answer, explanation, marks) values (2021, 54, '54', 'Set 2', 'Pure Aloha', 'NAT', 'Consider a network using the pure medium access control protocol, where each frame is of length bits. The channel transmission rate is Mbps ( bits per second). The aggregate number of transmissions across all the nodes (including new frame transmissions and retransmitted frames due to collisions) is modelled as a Poisson process with a rate of frames per second. Throughput is deﬁned as the average number of frames successfully transmitted per second. The throughput of the network (rounded to the nearest integer) is ______________', null::jsonb, '{"min": 130.0, "max": 140.0}'::jsonb, null, 2) on conflict (year, subject, original_label, set_label) do update set question_number = excluded.question_number, type = excluded.type, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer, marks = excluded.marks;
