insert into gate_questions (year, question_number, original_label, set_label, subject, type, question_text, options, correct_answer, explanation, marks) values (2023, 15, '15', null, 'Routing', 'MSQ', 'Which of the following statements is/are about the routing protocol used in the Internet?', '{"A": "implements Bellman-Ford algorithm to find shortest paths.", "B": "uses Dijkstra''s shortest path algorithm to implement least-cost path routing.", "C": "is used as an inter-domain routing protocol.", "D": "implements hierarchical routing."}'::jsonb, '["A", "C"]'::jsonb, null, 1) on conflict (year, subject, original_label, set_label) do update set question_number = excluded.question_number, type = excluded.type, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer, marks = excluded.marks;
