insert into gate_questions (year, question_number, original_label, set_label, subject, type, question_text, options, correct_answer, explanation, marks) values (2008, 67, '67', null, 'Routing', 'MCQ', 'Two popular routing algorithms are Distance Vector(DV) and Link State (LS) routing. Which of the following are true? (S1): Count to infinity is a problem only with DV and not LS routing (S2): In LS, the shortest path algorithm is run only at one node (S3): In DV, the shortest path algorithm is run only at one node (S4): DV requires lesser number of network messages than LS', '{"A": "S1, S2 and S4 only", "B": "S1, S3 and S4 only", "C": "S2 and S3 only", "D": "S1 and S4 only"}'::jsonb, '["D"]'::jsonb, null, 1) on conflict (year, subject, original_label, set_label) do update set question_number = excluded.question_number, type = excluded.type, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer, marks = excluded.marks;
insert into gate_questions (year, question_number, original_label, set_label, subject, type, question_text, options, correct_answer, explanation, marks) values (2014, 28, '28', 'Set 1', 'Sliding Window', 'NAT', 'Consider a selective repeat sliding window protocol that uses a frame size of to send data on a link with a one-way latency of . To achieve a link utilization of , the minimum number of bits required to represent the sequence number field is ________.', null::jsonb, '{"value": 5}'::jsonb, null, 1) on conflict (year, subject, original_label, set_label) do update set question_number = excluded.question_number, type = excluded.type, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer, marks = excluded.marks;
insert into gate_questions (year, question_number, original_label, set_label, subject, type, question_text, options, correct_answer, explanation, marks) values (2015, 28, '28', 'Set 3', 'Sliding Window', 'NAT', 'Consider a network connecting two systems located apart. The bandwidth of the network is per second. The propagation speed of the media is per second. It needs to design a Go-Back- sliding window protocol for this network. The average packet size is . The network is to be used to its full capacity. Assume that processing delays at nodes are negligible. Then, the minimum size in bits of the sequence number field has to be ______.', null::jsonb, '{"value": 8}'::jsonb, null, 1) on conflict (year, subject, original_label, set_label) do update set question_number = excluded.question_number, type = excluded.type, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer, marks = excluded.marks;
insert into gate_questions (year, question_number, original_label, set_label, subject, type, question_text, options, correct_answer, explanation, marks) values (2016, 55, '55', 'Set 2', 'Sliding Window', 'NAT', 'Consider a bits/second satellite communication link with one way propagation delay of milliseconds. Selective retransmission (repeat) protocol is used on this link to send data with a frame size of kilobyte. Neglect the transmission time of acknowledgement. The minimum number of bits required for the sequence number field to achieve utilization is ________.', null::jsonb, '{"value": 4}'::jsonb, null, 1) on conflict (year, subject, original_label, set_label) do update set question_number = excluded.question_number, type = excluded.type, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer, marks = excluded.marks;
insert into gate_questions (year, question_number, original_label, set_label, subject, type, question_text, options, correct_answer, explanation, marks) values (2015, 29, '29', 'Set 1', 'Slotted Aloha', 'NAT', 'Consider a LAN with four nodes and . Time is divided into ﬁxed-size slots, and a node can begin its transmission only at the beginning of a slot. A collision is said to have occurred if more than one node transmits in the same slot. The probabilities of generation of a frame in a time slot by and are and respectively. The probability of sending a frame in the ﬁrst slot without any collision by any of these four stations is__________________.', null::jsonb, '{"value": 0.4404}'::jsonb, null, 1) on conflict (year, subject, original_label, set_label) do update set question_number = excluded.question_number, type = excluded.type, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer, marks = excluded.marks;
insert into gate_questions (year, question_number, original_label, set_label, subject, type, question_text, options, correct_answer, explanation, marks) values (2015, 53, '53', 'Set 1', 'Stop and Wait', 'NAT', 'Suppose that the stop-and-wait protocol is used on a link with a bit rate of per second and propagation delay. Assume that the transmission time for the acknowledgment and the processing time at nodes are negligible. Then the minimum frame size in bytes to achieve a link utilization of at least is_________________.', null::jsonb, '{"value": 320}'::jsonb, null, 1) on conflict (year, subject, original_label, set_label) do update set question_number = excluded.question_number, type = excluded.type, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer, marks = excluded.marks;
insert into gate_questions (year, question_number, original_label, set_label, subject, type, question_text, options, correct_answer, explanation, marks) values (2016, 55, '55', 'Set 1', 'Stop and Wait', 'NAT', 'A sender uses the Stop-and-Wait protocol for reliable transmission of frames. Frames are of size bytes and the transmission rate at the sender is Size of an acknowledgment is bytes and the transmission rate at the receiver is The one-way propagation delay is milliseconds. Assuming no frame is lost, the sender throughput is ________ bytes/ second.', null::jsonb, '{"value": 2500}'::jsonb, null, 1) on conflict (year, subject, original_label, set_label) do update set question_number = excluded.question_number, type = excluded.type, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer, marks = excluded.marks;
