insert into gate_questions (year, question_number, original_label, set_label, subject, type, question_text, options, correct_answer, explanation, marks) values (2021, 44, '44', 'Set 1', 'TCP', 'MSQ', 'A server application is programmed to listen on port number on host . A client is connected to the server over the network. Consider that while the connection was active, the server machine crashed and rebooted. Assume that the client does not use the keepalive timer. Which of the following behaviors is/are possible?', '{"A": "If the client was waiting to receive a packet, it may wait indefinitely", "B": "The server application on can listen on after reboot", "C": "If the client sends a packet after the server reboot, it will receive a segment", "D": "If the client sends a packet after the server reboot, it will receive a segment"}'::jsonb, '["A", "B", "C"]'::jsonb, null, 2) on conflict (year, subject, original_label, set_label) do update set question_number = excluded.question_number, type = excluded.type, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer, marks = excluded.marks;
insert into gate_questions (year, question_number, original_label, set_label, subject, type, question_text, options, correct_answer, explanation, marks) values (2021, 45, '45', 'Set 1', 'TCP', 'MSQ', 'Consider two hosts and connected through a router . The maximum transfer unit value of the link between and is bytes, and between and is bytes. A segment of size bytes was transferred from to through , with identiﬁcation value as Assume that the header size is bytes. Further, the packet is allowed to be fragmented, i.e., flag in the header is set by . Which of the following statements is/are correct?', '{"A": "Two fragments are created at and the datagram size carrying the second fragment is bytes.", "B": "If the second fragment is lost, will resend the fragment with the identification value", "C": "If the second fragment is lost, is required to resend the whole segment.", "D": "destination port can be determined by analysing the second fragment."}'::jsonb, '["A", "C"]'::jsonb, null, 2) on conflict (year, subject, original_label, set_label) do update set question_number = excluded.question_number, type = excluded.type, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer, marks = excluded.marks;
insert into gate_questions (year, question_number, original_label, set_label, subject, type, question_text, options, correct_answer, explanation, marks) values (2021, 7, '7', 'Set 2', 'TCP', 'MCQ', 'Consider the three-way handshake mechanism followed during connection establishment between hosts and . Let and be two random -bit starting sequence numbers chosen by and respectively. Suppose sends a connection request message to with a segment having bit , number , and bit . Suppose accepts the connection request. Which one of the following choices represents the information present in the segment header that is sent by to ?', '{"A": "bit , number , bit , number , bit", "B": "bit , number , bit , number , bit", "C": "bit , number , bit , number , bit", "D": "bit , number , bit , number , bit"}'::jsonb, '["C"]'::jsonb, null, 1) on conflict (year, subject, original_label, set_label) do update set question_number = excluded.question_number, type = excluded.type, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer, marks = excluded.marks;
