insert into gate_questions (year, question_number, original_label, set_label, subject, type, question_text, options, correct_answer, explanation, marks) values (2024, 19, '19', 'Set 1', 'TCP', 'MSQ', '​ client successfully establishes a connection to server . Let denote the sequence number in the sent from to . Let denote the acknowledgement number in the SYN ACK from to . Which of the following statements is/are CORRECT?', '{"A": "The sequence number is chosen randomly by", "B": "The sequence number is always for a new connection", "C": "The acknowledgement number is equal to", "D": "The acknowledgement number is equal to"}'::jsonb, '["A", "D"]'::jsonb, null, 1) on conflict (year, subject, original_label, set_label) do update set question_number = excluded.question_number, type = excluded.type, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer, marks = excluded.marks;
insert into gate_questions (year, question_number, original_label, set_label, subject, type, question_text, options, correct_answer, explanation, marks) values (2026, 8, '8', 'Set 1', 'TCP', 'MCQ', 'With respect to a TCP connection between a client and a server, which one of the following statements is true?', '{"A": "The client and server use a two-way handshake mechanism before the start of data transmission", "B": "The server cannot initiate closing of the connection before the client initiates closing of the connection", "C": "The TCP connection is half-duplex", "D": "The client and server can initiate closing of the connection at the same time"}'::jsonb, '["D"]'::jsonb, null, 1) on conflict (year, subject, original_label, set_label) do update set question_number = excluded.question_number, type = excluded.type, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer, marks = excluded.marks;
