insert into gate_questions (year, question_number, original_label, set_label, subject, type, question_text, options, correct_answer, explanation, marks) values (2003, 86, '86', null, 'SQL', 'MCQ', 'Consider the set of relations shown below and the SQL query that follows. Students: (Roll_number, Name, Date_of_birth) Courses: (Course_number, Course_name, Instructor) Grades: (Roll_number, Course_number, Grade) Select distinct Name from Students , Courses , Grades where Students . Roll_number = Grades . Roll_number and Courses . Instructor = ''Korth'' and Courses . Course_number = Grades . Course_number and Grades . Grade = ''A'' Which of the following sets is computed by the above query?', '{"A": "Names of students who have got an A grade in all courses taught by Korth", "B": "Names of students who have got an A grade in all courses", "C": "Names of students who have got an A grade in at least one of the courses taught by Korth", "D": "None of the above"}'::jsonb, '["C"]'::jsonb, null, 1) on conflict (year, subject, original_label, set_label) do update set question_number = excluded.question_number, type = excluded.type, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer, marks = excluded.marks;
insert into gate_questions (year, question_number, original_label, set_label, subject, type, question_text, options, correct_answer, explanation, marks) values (2004, 53, '53', null, 'SQL', 'MCQ', 'The employee information in a company is stored in the relation Employee (name, sex, salary, deptName) Consider the following SQL query Select deptName From Employee Where sex = ‘ M ’ Group by deptName Having avg ( salary ) > ( select avg ( salary ) from Employee ) It returns the names of the department in which', '{"A": "the average salary is more than the average salary in the company", "B": "the average salary of male employees is more than the average salary of all male employees in the company", "C": "the average salary of male employees is more than the average salary of employees in same the department", "D": "the average salary of male employees is more than the average salary in the company"}'::jsonb, '["D"]'::jsonb, null, 1) on conflict (year, subject, original_label, set_label) do update set question_number = excluded.question_number, type = excluded.type, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer, marks = excluded.marks;
