insert into gate_questions (year, question_number, original_label, set_label, subject, type, question_text, options, correct_answer, explanation, marks) values (2019, 17, '17', null, 'Fork System Call', 'NAT', 'The following C program is executed on a Unix/Linux system : #include <unistd.h> int main () 5.10.5', null::jsonb, '{"value": 31}'::jsonb, null, 1) on conflict (year, subject, original_label, set_label) do update set question_number = excluded.question_number, type = excluded.type, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer, marks = excluded.marks;
insert into gate_questions (year, question_number, original_label, set_label, subject, type, question_text, options, correct_answer, explanation, marks) values (2024, 47, '47', 'Set 1', 'Fork System Call', 'NAT', 'Consider the following code snippet using the fork () and wait () system calls. Assume that the code compiles and runs correctly, and that the system calls run successfully without any errors. int x = 3 ; while ( x > 0 ){ fork (); printf ( "hello" ); wait ( NULL ) ; X -- ; } The total number of times the printf statement is executed is __________.', null::jsonb, '{"value": 14}'::jsonb, null, 2) on conflict (year, subject, original_label, set_label) do update set question_number = excluded.question_number, type = excluded.type, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer, marks = excluded.marks;
insert into gate_questions (year, question_number, original_label, set_label, subject, type, question_text, options, correct_answer, explanation, marks) values (2026, 53, '53', 'Set 1', 'Fork System Call', 'NAT', 'Consider the following program snippet. Assume that the program compiles and runs successfully. Further, assume that the fork() system call is always successful in creating a process. int main () { int i ; for ( i = 0 ; i < 3 ; i ++) { if ( fork () == 0 ) { continue ; } break ; } printf ( "Hello!" ); return 0 ; } The total number of times that the printf statement gets executed is . (answer in integer)', null::jsonb, '{"min": 4.0, "max": 4.0}'::jsonb, null, 2) on conflict (year, subject, original_label, set_label) do update set question_number = excluded.question_number, type = excluded.type, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer, marks = excluded.marks;
