insert into gate_questions (year, question_number, original_label, set_label, subject, type, question_text, options, correct_answer, explanation, marks) values (1998, 1, '1.29', null, 'IO Handling', 'MCQ', 'Which of the following is an example of a spooled device?', '{"A": "The terminal used to enter the input data for the C program being executed", "B": "An output device used to print the output of a number of jobs", "C": "The secondary memory device in a virtual storage system", "D": "The swapping area on a disk used by the swapper"}'::jsonb, '["B"]'::jsonb, null, 1) on conflict (year, subject, original_label, set_label) do update set question_number = excluded.question_number, type = excluded.type, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer, marks = excluded.marks;
