insert into gate_questions (year, question_number, original_label, set_label, subject, type, question_text, options, correct_answer, explanation, marks) values (2005, 20, '20', null, 'IO Handling', 'MCQ', 'Normally user programs are prevented from handling I/O directly by I/O instructions in them. For CPUs having explicit I/O instructions, such I/O protection is ensured by having the I/O instruction privileged. In a 5.11.5', '{"A": "QPTRS", "B": "PTRSQ", "C": "TRPQS", "D": "QTPRS"}'::jsonb, '["A"]'::jsonb, null, 1) on conflict (year, subject, original_label, set_label) do update set question_number = excluded.question_number, type = excluded.type, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer, marks = excluded.marks;
insert into gate_questions (year, question_number, original_label, set_label, subject, type, question_text, options, correct_answer, explanation, marks) values (2025, 19, '19', 'Set 1', 'Input Output', 'NAT', 'Suppose in a multiprogramming environment, the following C program segment is executed. A process goes into I/O queue whenever an I/O related operation is performed. Assume that there will always be a context switch whenever a process requests for an I/O, and also whenever the process returns from an I/O. The number of times the process will enter the ready queue during its lifetime (not counting the time the process enters the ready queue when it is run initially) is ___________ . Answer in integer) int main () { µ µ 5.13 5.13.1 5.14 5.14.1 5.14.2 int x = 0 , i = 0 ; scanf ( "%d" ,& x ); for ( i = 0 ; i < 20 ; i ++) { x = x + 20 ; printf ( "%d\n" , x ); } return 0 ; }', null::jsonb, '{"min": 21.0, "max": 21.0}'::jsonb, null, 1) on conflict (year, subject, original_label, set_label) do update set question_number = excluded.question_number, type = excluded.type, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer, marks = excluded.marks;
