insert into gate_questions (year, question_number, original_label, set_label, subject, type, question_text, options, correct_answer, explanation, marks) values (2021, 48, '48', 'Set 2', 'Page Replacement', 'NAT', 'Consider a three-level page table to translate a bit virtual address to a physical address as shown below: The page size is bytes and page table entry size at every level is bytes. A process is currently using bytes virtual memory which is mapped to of physical memory. The minimum amount of memory required for the page table of across all levels is _________ .', null::jsonb, '{"min": 4108.0, "max": 4108.0}'::jsonb, null, 2) on conflict (year, subject, original_label, set_label) do update set question_number = excluded.question_number, type = excluded.type, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer, marks = excluded.marks;
insert into gate_questions (year, question_number, original_label, set_label, subject, type, question_text, options, correct_answer, explanation, marks) values (2025, 44, '44', 'Set 1', 'Page Replacement', 'NAT', 'In optimal page replacement algorithm, information about all future page references is available to the operating system (OS). A modification of the optimal page replacement algorithm is as follows: The OS correctly predicts only up to next page references (including the current page) at the time of allocating a frame to a page. A process accesses the pages in the following order of page numbers: If the system has three memory frames that are initially empty, the number of page faults that will occur during execution of the process is __________. (Answer in integer)', null::jsonb, '{"min": 6.0, "max": 6.0}'::jsonb, null, 2) on conflict (year, subject, original_label, set_label) do update set question_number = excluded.question_number, type = excluded.type, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer, marks = excluded.marks;
insert into gate_questions (year, question_number, original_label, set_label, subject, type, question_text, options, correct_answer, explanation, marks) values (1996, 1, '1.18', null, 'Process', 'MCQ', 'The process state transition diagram in the below figure is representative of', '{"A": "a batch operating system", "B": "an operating system with a preemptive scheduler", "C": "an operating system with a non-preemptive scheduler", "D": "a uni-programmed operating system"}'::jsonb, '["B"]'::jsonb, null, 1) on conflict (year, subject, original_label, set_label) do update set question_number = excluded.question_number, type = excluded.type, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer, marks = excluded.marks;
insert into gate_questions (year, question_number, original_label, set_label, subject, type, question_text, options, correct_answer, explanation, marks) values (2001, 2, '2.20', null, 'Process', 'MCQ', 'Which of the following does not interrupt a running process?', '{"A": "Page table base register", "B": "Stack pointer", "C": "Program counter", "D": "General purpose registers"}'::jsonb, '["C"]'::jsonb, null, 1) on conflict (year, subject, original_label, set_label) do update set question_number = excluded.question_number, type = excluded.type, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer, marks = excluded.marks;
insert into gate_questions (year, question_number, original_label, set_label, subject, type, question_text, options, correct_answer, explanation, marks) values (2002, 2, '2.21', null, 'Process', 'MCQ', 'Which combination of the following features will suffice to characterize an OS as a multi-programmed OS? a . More than one program may be loaded into main memory at the same time for execution b . If a program waits for certain events such as I/O, another program is immediately scheduled for execution c . If the execution of a program terminates, another program is immediately scheduled for execution.', '{"A": "(a)", "B": "(a) and (b)", "C": "(a) and (c)", "D": "(a), (b) and (c)"}'::jsonb, '["B"]'::jsonb, null, 1) on conflict (year, subject, original_label, set_label) do update set question_number = excluded.question_number, type = excluded.type, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer, marks = excluded.marks;
insert into gate_questions (year, question_number, original_label, set_label, subject, type, question_text, options, correct_answer, explanation, marks) values (1998, 7, '7-b', null, 'Process Scheduling', 'NAT', 'In a computer system where the ‘best-ﬁt’ algorithm is used for allocating ‘jobs’ to ‘memory partitions’, the following situation was encountered: When will the job complete?', null::jsonb, '{"value": 19}'::jsonb, null, 1) on conflict (year, subject, original_label, set_label) do update set question_number = excluded.question_number, type = excluded.type, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer, marks = excluded.marks;
