insert into gate_questions (year, question_number, original_label, set_label, subject, type, question_text, options, correct_answer, explanation, marks) values (2020, 50, '50', null, 'Process Scheduling', 'NAT', 'Consider the following set of processes, assumed to have arrived at time . Consider the CPU scheduling algorithms Shortest Job First (SJF) and Round Robin (RR). For RR, assume that the processes are scheduled in the order . If the time quantum for RR is ms, then the absolute value of the diﬀerence between the average turnaround times (in ms) of SJF and RR (round off to decimal places is_______', null::jsonb, '{"min": 5.25, "max": 5.26}'::jsonb, null, 2) on conflict (year, subject, original_label, set_label) do update set question_number = excluded.question_number, type = excluded.type, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer, marks = excluded.marks;
insert into gate_questions (year, question_number, original_label, set_label, subject, type, question_text, options, correct_answer, explanation, marks) values (2021, 25, '25', 'Set 1', 'Process Scheduling', 'NAT', 'Three processes arrive at time zero with bursts of and milliseconds. If the scheduler has prior knowledge about the length of the bursts, the minimum achievable average waiting time for these three processes in a non-preemptive scheduler (rounded to nearest integer) is _____________ milliseconds.', null::jsonb, '{"min": 12.0, "max": 12.0}'::jsonb, null, 1) on conflict (year, subject, original_label, set_label) do update set question_number = excluded.question_number, type = excluded.type, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer, marks = excluded.marks;
insert into gate_questions (year, question_number, original_label, set_label, subject, type, question_text, options, correct_answer, explanation, marks) values (2021, 14, '14', 'Set 2', 'Process Scheduling', 'MSQ', 'Which of the following statement(s) is/are correct in the context of scheduling?', '{"A": "Turnaround time includes waiting time", "B": "The goal is to only maximize utilization and minimize throughput", "C": "Round-robin policy can be used even when the time required by each of the processes is not known apriori", "D": "Implementing preemptive scheduling needs hardware support"}'::jsonb, '["A", "C", "D"]'::jsonb, null, 1) on conflict (year, subject, original_label, set_label) do update set question_number = excluded.question_number, type = excluded.type, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer, marks = excluded.marks;
insert into gate_questions (year, question_number, original_label, set_label, subject, type, question_text, options, correct_answer, explanation, marks) values (2025, 28, '28', 'Set 1', 'Process Scheduling', 'MCQ', 'A computer has two processors, and . Four processes with CPU bursts of , and milliseconds, respectively, arrive at the same time and these are the only processes in the system. The scheduler uses non-preemptive priority scheduling, with priorities decided as follows: uses priority of execution for the processes as, , i.e., and have highest and lowest priorities, respectively. uses priority of execution for the processes as, , i.e., and have highest and lowest priorities, respectively. A process is scheduled to a processor , if the processor is free and no other process is waiting with higher priority. At any given point of time, a process can be allocated to any one of the free processors without violating the execution priority rules. Ignore the context switch time. What will be the average waiting time of the processes in milliseconds?', '{"A": "Shortest Remaining Time First (SRTF) Scheduling", "B": "First Come First Serve (FCFS) Scheduling", "C": "Round Robin Scheduling", "D": "Priority Scheduling"}'::jsonb, '["A"]'::jsonb, null, 2) on conflict (year, subject, original_label, set_label) do update set question_number = excluded.question_number, type = excluded.type, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer, marks = excluded.marks;
insert into gate_questions (year, question_number, original_label, set_label, subject, type, question_text, options, correct_answer, explanation, marks) values (2026, 54, '54', 'Set 1', 'Process Scheduling', 'NAT', 'Consider a CPU that has to execute two types of processes. The ﬁrst type, Actuators (A), requires a CPU burst of seconds. The second type, Controllers (C), requires a CPU burst of seconds. A new process of type A arrives at time , , and (in seconds). Similarly, a new process of type C arrives at time , and (in seconds). The CPU scheduling policy is First Come First Serve (FCFS). The ﬁrst process of type A starts running at seconds. The average waiting time (in seconds) for the processes is . (rounded off to one decimal place)', null::jsonb, '{"min": 9.5, "max": 9.5}'::jsonb, null, 2) on conflict (year, subject, original_label, set_label) do update set question_number = excluded.question_number, type = excluded.type, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer, marks = excluded.marks;
