insert into gate_questions (year, question_number, original_label, set_label, subject, type, question_text, options, correct_answer, explanation, marks) values (2008, 67, '67', null, 'Virtual Memory', 'MCQ', 'A processor uses bit physical address and bit virtual addresses, with a page frame size of Kbytes. Each page table entry is of size bytes. A three level page table is used for virtual to physical address translation, where the virtual address is used as follows: Bits are used to index into the first level page table. Bits are used to index into the 2nd level page table. Bits are used to index into the 3rd level page table. Bits are used as offset within the page. The number of bits required for addressing the next level page table(or page frame) in the page table entry of the first, second and third level page tables are respectively', '{"A": "Virtual page number", "B": "Page frame number", "C": "Both virtual page number and page frame number", "D": "Access right information"}'::jsonb, '["D"]'::jsonb, null, 1) on conflict (year, subject, original_label, set_label) do update set question_number = excluded.question_number, type = excluded.type, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer, marks = excluded.marks;
insert into gate_questions (year, question_number, original_label, set_label, subject, type, question_text, options, correct_answer, explanation, marks) values (2009, 34, '34', null, 'Virtual Memory', 'MCQ', 'A multilevel page table is preferred in comparison to a single level page table for translating virtual address to physical address because', '{"A": "It reduces the memory access time to read or write a memory location.", "B": "It helps to reduce the size of page table needed to implement the virtual address space of a process", "C": "It is required by the translation lookaside buffer.", "D": "It helps to reduce the number of page faults in page replacement algorithms."}'::jsonb, '["B"]'::jsonb, null, 1) on conflict (year, subject, original_label, set_label) do update set question_number = excluded.question_number, type = excluded.type, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer, marks = excluded.marks;
