insert into gate_questions (year, question_number, original_label, set_label, subject, type, question_text, options, correct_answer, explanation, marks) values (2020, 53, '53', null, 'Virtual Memory', 'NAT', 'Consider a paging system that uses -level page table residing in main memory and a for address translation. Each main memory access takes ns and lookup takes ns. Each page transfer to/from the disk takes ns. Assume that the hit ratio is , page fault rate is . Assume that for of the total page faults, a dirty page has to be written back to disk before the required page is read from disk. update time is negligible. The average memory access time in ns (round oﬀ to decimal places) is ___________', null::jsonb, '{"min": 155.0, "max": 156.0}'::jsonb, null, 2) on conflict (year, subject, original_label, set_label) do update set question_number = excluded.question_number, type = excluded.type, question_text = excluded.question_text, options = excluded.options, correct_answer = excluded.correct_answer, marks = excluded.marks;
